<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Product extends Model {protected $guarded=[]; protected $casts=['colours'=>'array','sizes'=>'array','spin_images'=>'array','is_new'=>'boolean','is_active'=>'boolean']; public function category(){return $this->belongsTo(Category::class);} public function variants(){return $this->hasMany(ProductVariant::class);} public function reviews(){return $this->hasMany(Review::class)->where('status','approved');} }
